// src/app/components/game-components/rectangular-game-component/RectangularGameComponent.ts
var RectangularGameComponent = class extends GameComponent {
  constructor(urlName) {
    super(urlName);
  }
  board;
  getWidth() {
    return this.getState().getWidth();
  }
  getHeight() {
    return this.getState().getHeight();
  }
  computeViewBox() {
    const width = this.getWidth() * this.SPACE_SIZE;
    const height = this.getHeight() * this.SPACE_SIZE;
    return this.getViewBoxFor(width, height);
  }
  getViewBoxFor(width, height) {
    const halfStroke = 0.5 * this.STROKE_WIDTH;
    return ViewBox.fromLimits(0, width, 0, height).expandAll(halfStroke);
  }
};

// src/app/components/game-components/parallelogram-game-component/ParallelogramGameComponent.ts
var ParallelogramGameComponent = class extends RectangularGameComponent {
  constructor(urlName) {
    super(urlName);
  }
  getParallelogramCoords(mode) {
    const parallelogramHeight = mode.parallelogramHeight;
    const parallelogramWidth = parallelogramHeight * mode.horizontalWidthRatio;
    const parallelogramOffset = parallelogramHeight * mode.offsetRatio;
    const x1 = parallelogramWidth;
    const y1 = 0;
    const x2 = parallelogramWidth - parallelogramOffset;
    const y2 = parallelogramHeight;
    const x3 = -parallelogramOffset;
    const y3 = parallelogramHeight;
    return [
      new Coord(0, 0),
      new Coord(x1, y1),
      new Coord(x2, y2),
      new Coord(x3, y3)
    ];
  }
  /**
   * @param x the x coord on the state of the piece to draw
   * @param y the y coord on the state of the piece to draw
   * @param z the z coord on the state of the piece to draw
   * @param mode the mode in which the component is to be drawn
   * @returns the coord(x, y) of the upper left parallelogram to draw on the SVG;
   */
  getCoordTranslation(x2, y, z, mode) {
    const spaceHeight = mode.parallelogramHeight;
    const spaceWidth = spaceHeight * mode.horizontalWidthRatio;
    const spaceOffset = mode.offsetRatio * spaceHeight;
    const numberOfOffset = this.getState().getHeight() - y;
    const xBase = x2 * spaceWidth + numberOfOffset * spaceOffset;
    const yBase = y * spaceHeight - mode.pieceHeightRatio * spaceHeight * z;
    return new Coord(xBase, yBase);
  }
};

// src/app/games/checkers/common/CheckersControlHeuristic.ts
var CheckersControlHeuristic = class extends PlayerMetricHeuristic {
  rules;
  constructor(rules) {
    super();
    this.rules = rules;
  }
  getMetrics(node, config) {
    return this.getControlScore(node, config);
  }
  getControlScore(node, config) {
    const state = node.gameState;
    const controlScores = PlayerNumberTable.of([0], [0]);
    for (const player of Player.PLAYERS) {
      const numberOfMobileCoords = this.getNumberOfMobileCoords(state, player, config);
      controlScores.add(player, 0, numberOfMobileCoords);
    }
    return controlScores;
  }
  getNumberOfMobileCoords(state, player, config) {
    const potentialMoves = this.getCapturesAndSteps(state, player, config);
    const firstCoords = potentialMoves.map((move) => move.getStartingCoord());
    const uniqueFirstCoords = new CoordSet(firstCoords);
    return uniqueFirstCoords.size();
  }
  getCapturesAndSteps(state, player, config) {
    const captures = this.rules.getCapturesOf(state, player, config);
    const steps = this.rules.getStepsOf(state, player, config);
    return captures.concat(steps);
  }
};

// src/app/games/checkers/common/CheckersControlPlusDominationHeuristic.ts
var CheckersControlPlusDominationHeuristic = class extends CheckersControlHeuristic {
  getMetrics(node, config) {
    const controlValue = this.getControlScore(node, config);
    const dominatingPiecesCount = this.getDominatedPieceScore(node);
    return controlValue.concat(dominatingPiecesCount);
  }
  getDominatedPieceScore(node) {
    const dominatedPieces = PlayerNumberTable.of([0], [0]);
    const state = node.gameState;
    const width = state.getWidth();
    const height = state.getHeight();
    for (let y = 0; y < height; y++) {
      for (let x2 = 0; x2 < width; x2++) {
        const square = state.getPieceAtXY(x2, y);
        if (square.getStackSize() > 0) {
          const stackSize = square.getStackSize();
          let pieceIndex = 0;
          const commander = square.getCommander().player;
          while (pieceIndex < stackSize && square.get(pieceIndex).player === commander) {
            pieceIndex++;
          }
          dominatedPieces.add(commander, 0, pieceIndex);
        }
      }
    }
    return dominatedPieces;
  }
};

// src/app/games/checkers/common/CheckersMoveGenerator.ts
var CheckersMoveGenerator = class extends MoveGenerator {
  rules;
  constructor(rules) {
    super();
    this.rules = rules;
  }
  getListMoves(node, config) {
    const captures = this.getLegalCaptures(node.gameState, config);
    if (captures.length > 0) {
      return captures;
    } else {
      return this.rules.getSteps(node.gameState, config);
    }
  }
  getLegalCaptures(state, config) {
    const possibleCaptures = this.rules.getCompleteCaptures(state, config);
    if (config.mustMakeMaximalCapture) {
      return ArrayUtils.maximumsBy(possibleCaptures, (m2) => m2.coords.length);
    } else {
      return possibleCaptures;
    }
  }
};

// src/app/games/checkers/common/CheckersScoreHeuristic.ts
var CheckersScoreHeuristic = class extends PlayerMetricHeuristic {
  getMetrics(node, _config) {
    return node.gameState.getScores().toTable();
  }
};

